/* 재현: APP_URL=http://127.0.0.1:8093 node docs/testing/repro/negative-78.cjs
 * 별도 Chromium 프로세스 + 항목별 격리 BrowserContext. 실제 API 호출은 차단한다.
 * ONLY=7,8 로 선택 실행 가능. 기존 결과는 실행할 때 덮어쓴다.
 */
const { chromium } = require('playwright');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const ROOT = path.resolve(__dirname, '../../..');
const OUT = process.env.NEGATIVE_OUT || path.join(ROOT, 'docs/testing/evidence/negative-78');
const BASE = process.env.APP_URL || 'http://127.0.0.1:8093';
const KEY = 'routeflow.travels.v1';
const D = '2026-11-01', E = '2026-11-02';
const headers = ['장소','날짜','시간','지역','메모','주소','위도','경도'];
const mapping = { name:0,date:1,category:1,time:2,region:3,memo:4,address:5,lat:6,lng:7,mode:-1 };
function trip(id='negative-A', name='부정 테스트 A', rows=[['첫 장소',D,'10:00–11:00'],['둘째 장소',D,'12:00–13:00'],['셋째 장소',E,'10:00–11:00']]) {
  return { id,name,updated:Date.now(),headers,mapping,dates:[D,E,'2026-11-03'],library:[],sheetName:'일정',region:'',
    records:rows.map((r,i)=>({rowNumber:i+2,cells:[r[0],r[1]??D,r[2]??'',r[3]??'',r[4]??'',r[5]??'테스트 주소',r[6]??35+i*.02,r[7]??139+i*.02].map(v=>({t:typeof v==='number'?'n':'s',v}))})),
    places:rows.map((r,i)=>({recordIndex:i,status:'confirmed',cachedAt:Date.now(),place:{id:'p'+i,name:r[0],address:'테스트 주소',lat:r[6]??35+i*.02,lng:r[7]??139+i*.02,url:''}})) };
}
let browser; const results=[];
const cases = new Map();
function test(id, steps, fn) { cases.set(id,{steps,fn}); }
const wait = (p,ms=650)=>p.waitForTimeout(ms);
async function store(p) { await wait(p); return p.evaluate(k=>JSON.parse(localStorage.getItem(k)||'{}'),KEY); }
async function snap(p,id='negative-A') { return (await store(p))[id]; }
const names = s => s?.records?.map(r=>r.cells?.[0]?.v);
async function close(p) { await p.evaluate(()=>document.querySelectorAll('dialog[open]').forEach(d=>d.close())); await wait(p,30); }
async function openTrip(p,id='negative-A') { await close(p); await p.click('#savedTravels');await p.locator('#travelHistoryDialog').waitFor({state:'visible'}); await p.click(`[data-travel-open="${id}"]`); await p.locator("#travelHistoryDialog").waitFor({state:"hidden"}); await wait(p,70); }
async function edit(p,n=0) { await close(p); await p.click('#travelPlanTab'); await p.locator('#resultList [data-action="edit"]').nth(n).click(); }
async function add(p,name='추가 장소',date=D,time='',memo='') { await close(p); await p.click('#travelPlanTab'); await p.click('#scheduleAdd'); await p.fill('#scheduleName',name); await p.fill('#scheduleDate',date); await p.fill('#scheduleTime',time); await p.fill('#scheduleMemo',memo); await p.click('#scheduleForm button[type=submit]'); await wait(p,550); }
async function del(p,n=0,accept=true) { await close(p); p.once('dialog',d=>accept?d.accept():d.dismiss()); await p.locator('#resultList [data-action="delete"]').nth(n).click(); }
async function move(p,n=0,day=E,pos='end') { await close(p); await p.locator('#resultList [data-action="travel-move"]').nth(n).click(); await p.fill('#travelAssignDay',day); await p.selectOption('#travelAssignPosition',pos); await p.click('#travelAssignForm button'); await wait(p,50); }
async function newTrip(p,name='부정 테스트 새 여행',start=D,days='3',raw=false) { await close(p); await p.click('#newTravel'); await p.fill('#travelName',name); await p.fill('#travelStart',start); await p.fill('#travelDays',days); if(raw) await p.evaluate(()=>document.querySelector('#newTravelForm').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}))); else await p.click('#newTravelForm button'); await wait(p,40); }
async function search(p,q,config) { await close(p); await p.click('#travelLibraryTab'); if(config)await p.evaluate(([q,c])=>window.__mock.query[q]=c,[q,config]); await p.fill('#travelSearch',q); await p.locator('#travelSearchForm button').click(); await wait(p,70); }
async function drop(p,source,target,cancel=false) { await p.evaluate(([s,t,c])=>{const dataTransfer=new DataTransfer();const a=document.querySelector(s),b=document.querySelector(t);a.dispatchEvent(new DragEvent('dragstart',{bubbles:true,dataTransfer}));if(!c)b.dispatchEvent(new DragEvent('drop',{bubbles:true,dataTransfer}));a.dispatchEvent(new DragEvent('dragend',{bubbles:true,dataTransfer}));},[source,target,cancel]); }
const place=(id='mock1',name='모의 장소',extra={})=>({id,name,address:'일본 도쿄 테스트 1',lat:35.1,lng:139.1,...extra});
async function file(p,buffer,name='negative.xlsx') { await close(p); await p.setInputFiles('#fileInput',{name,mimeType:'application/octet-stream',buffer}); await wait(p,150); }
async function workbook(p,aoa,special={}) { const arr=await p.evaluate(({aoa,special})=>{const w=XLSX.utils.book_new(),s=XLSX.utils.aoa_to_sheet(aoa);Object.assign(s,special);XLSX.utils.book_append_sheet(w,s,'일정');return Array.from(new Uint8Array(XLSX.write(w,{type:'array',bookType:'xlsx'})));},{aoa,special});return Buffer.from(arr); }

test(7,'정상 저장본 확보 → Storage.setItem에 QuotaExceededError/일반 쓰기 오류 주입 → 일정 수정 → 저장 상태·원본 비교',async(p,c,check)=>{
 const before=await snap(p); await p.evaluate(()=>{window.__originalSet=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(k==='routeflow.travels.v1')throw new DOMException('test quota','QuotaExceededError');return window.__originalSet.call(this,k,v);};});
 await add(p,'용량 초과 후 추가');check('용량 초과 시 실패 안내',/부족/.test(await p.textContent('#travelSaveStatus')),await p.textContent('#travelSaveStatus'));
 check('이전 정상 저장본 보존',JSON.stringify((await snap(p)).records)===JSON.stringify(before.records),'저장 records 비교');
 await p.evaluate(()=>{Storage.prototype.setItem=function(k,v){if(k==='routeflow.travels.v1')throw new Error('write denied');return window.__originalSet.call(this,k,v);};});await add(p,'일반 실패');check('일반 쓰기 실패 안내',/부족/.test(await p.textContent('#travelSaveStatus')),await p.textContent('#travelSaveStatus'));
});
test(8,'동일 BrowserContext의 두 탭에서 A 열기 → 1탭 수정, 2탭 수정/삭제 → 저장소 비교',async(p,c,check)=>{
 const q=await c.newPage(); await q.goto(BASE); await openTrip(q); await edit(p);await p.fill('#scheduleMemo','첫 탭 메모');await p.click('#scheduleForm button[type=submit]');await wait(p);
 await edit(q,1);await q.fill('#scheduleMemo','둘째 탭 메모');await q.click('#scheduleForm button[type=submit]');await wait(q);
 const after=await snap(q);check('다중 탭 수정 충돌 감지/보존',after.records[0].cells[4].v==='첫 탭 메모',{firstMemo:after.records[0].cells[4].v,secondMemo:after.records[1].cells[4].v});
 await close(p);await p.click('#savedTravels');await p.locator('#travelHistoryDialog').waitFor({state:'visible'});p.once('dialog',d=>d.accept());await p.click('[data-travel-delete="negative-A"]');await close(p);
 await edit(q);await q.fill('#scheduleMemo','삭제 후 오래된 탭 수정');await q.click('#scheduleForm button[type=submit]');await wait(q);check('다른 탭에서 삭제한 여행 부활 방지',!(await store(q))['negative-A'],Object.keys(await store(q)));await q.close();
});
test(57,'현재 여행 저장본 삭제 확인 → 열린 여행 수정 → 자동 저장 → 새로고침',async(p,c,check)=>{await p.click('#savedTravels');await p.locator('#travelHistoryDialog').waitFor({state:'visible'});p.once('dialog',d=>d.accept());await p.click('[data-travel-delete="negative-A"]');await close(p);await add(p,'삭제 후 편집');check('자동 저장 부활 방지',!(await store(p))['negative-A'],Object.keys(await store(p)));await p.reload();check('새로고침 후에도 없음',!(await store(p))['negative-A'],Object.keys(await store(p)));});
test(58,'정상 여행 옆에 records가 null인 손상 여행 주입 → 손상 여행 열기 → 정상 저장본/오류 안내 확인',async(p,c,check)=>{
 const before=await snap(p);await p.evaluate(k=>{const a=JSON.parse(localStorage.getItem(k));a.bad={...a['negative-A'],id:'bad',records:null};localStorage.setItem(k,JSON.stringify(a));},KEY);
 await close(p);let appError='';p.once('pageerror',e=>appError=e.message);await p.click('#savedTravels');await p.locator('#travelHistoryDialog').waitFor({state:'visible'});await wait(p,50);check('손상 데이터 명확한 오류 안내',!appError,{appError,history:await p.textContent('#travelHistoryList')});check('손상 목록의 오류 안내와 정상 목록 유지',await p.locator('[data-travel-open="negative-A"]').count()>0,{history:await p.textContent('#travelHistoryList')});check('정상 여행 저장본 보존',JSON.stringify((await snap(p)).records)===JSON.stringify(before.records),'저장소 비교');
});
test(60,'저장 여행 id를 다른 여행 ID로 변조 → 열어 편집; updated/records/library 타입 변조는 별도 페이지로 검사',async(p,c,check)=>{
 await p.reload();await p.evaluate(k=>{const a=JSON.parse(localStorage.getItem(k));a['negative-A'].id='negative-B';a['negative-A'].updated=Date.now()+10000;localStorage.setItem(k,JSON.stringify(a));},KEY);await p.click('#savedTravels');await p.locator('#travelHistoryDialog').waitFor({state:'visible'});await p.locator('#travelHistoryList').waitFor({state:'visible'});check('ID 불일치 여행 열기 차단',await p.locator('[data-travel-open="negative-A"]').count()===0,{history:await p.textContent('#travelHistoryList')});const a=await store(p);check('ID 변조로 다른 여행 덮어쓰기 방지',names(a['negative-B']).join()==='다른 여행 장소',{B:a['negative-B'].name,records:names(a['negative-B'])});
});
test(9,'첫 장소 이동 → 삭제 → 되돌리기 → 날짜 필터 → B/A 여행 전환 → 데이터·모의 핀 확인',async(p,c,check)=>{await move(p,0,E);await del(p,0);await p.click('#toastUndo');await openTrip(p,'negative-B');await openTrip(p);const s=await snap(p);check('다른 여행 오염 없이 이동·삭제 취소 유지',s.records.length===3&&s.records.find(r=>r.cells[0].v==='첫 장소').cells[1].v===E,{rows:s.records.map(r=>[r.cells[0].v,r.cells[1].v])});check('현재 여행 모의 핀 수',Object.values(await p.evaluate(()=>__mock.markers)).filter(m=>m.position&&m.label!=='☆').length===3,await p.evaluate(()=>__mock.markers));await del(p,0);await openTrip(p,'negative-B');check('전환 시 이전 undo 비활성',!await p.locator('#toastUndo').isVisible());await p.evaluate(()=>document.querySelector('#toastUndo').click());check('여행 전환 뒤 이전 삭제 undo의 다른 여행 오염 방지',names(await snap(p,'negative-B')).join()==='다른 여행 장소',{B:names(await snap(p,'negative-B')),A:names(await snap(p))});});
test(3,'수정 중 새로고침/탭 종료/뒤로가기, 드래그 확정 직후 새로고침',async(p,c,check)=>{await edit(p);await p.fill('#scheduleMemo','미저장 초안');let warning=false;p.on('dialog',async d=>{warning=true;await d.dismiss();});await p.reload();await openTrip(p);await edit(p);check('새로고침 미저장 초안 보호',warning||await p.inputValue('#scheduleMemo')==='미저장 초안',{warning,memo:await p.inputValue('#scheduleMemo')});await close(p);await move(p,0,E);await p.reload();await openTrip(p);check('확정 이동 새로고침 복원',(await snap(p)).records.some(r=>r.cells[0].v==='첫 장소'&&r.cells[1].v===E),'저장 날짜 확인');});
test(10,'HTML 이벤트 문자열·100k 메모 저장, 잘못된 좌표, 손상 파일/저장 데이터 별도 검사',async(p,c,check)=>{await add(p,'<img src=x onerror="window.__xss=1">',D,'','메'.repeat(100000));const s=await snap(p);check('HTML 문자열 비실행',!(await p.evaluate(()=>window.__xss)),await p.locator('#resultList .item-name').allTextContents());check('긴 메모 저장/응답 유지',s.records.some(r=>r.cells[4]?.v?.length===100000),'100000자 보존');await p.reload();await p.evaluate(k=>{const a=JSON.parse(localStorage.getItem(k));a['negative-A'].places=[];a['negative-A'].records[0].cells[6].v=999;a['negative-A'].records[0].cells[7].v=999;localStorage.setItem(k,JSON.stringify(a));},KEY);await openTrip(p);const markers=await p.evaluate(()=>__mock.markers);check('범위 밖 좌표 핀 제외',!markers[0]?.position,markers[0]);});
test(11,'새 여행 이름 공백·줄바꿈만 제출',async(p,c,check)=>{const n=Object.keys(await store(p)).length;await newTrip(p,'   ');check('공백 이름 거부',Object.keys(await store(p)).length===n,Object.values(await store(p)).map(t=>t.name));await close(p);await newTrip(p,'\n\n');check('줄바꿈 이름 거부',Object.keys(await store(p)).length===n,Object.values(await store(p)).map(t=>t.name));});
test(12,'같은 이름 여행 두 개 생성 → 저장 목록 구분·별도 ID 확인',async(p,c,check)=>{await newTrip(p,'동일 이름',D);await newTrip(p,'동일 이름',E);await p.click('#savedTravels');await p.locator('#travelHistoryDialog').waitFor({state:'visible'});const a=Object.values(await store(p)).filter(t=>t.name==='동일 이름');check('같은 이름 별도 ID',a.length===2&&a[0].id!==a[1].id,a.map(t=>({id:t.id,dates:t.dates})));check('목록 구분 정보',await p.locator('#travelHistoryList article').count()>=4,await p.textContent('#travelHistoryList'));});
test(13,'0·-1·1.5·1000일 HTML 제출과 submit 이벤트 직접 호출로 처리 단계 검증',async(p,c,check)=>{for(const v of ['0','-1','1.5','1000']){let n=Object.keys(await store(p)).length;await newTrip(p,'일수 '+v,D,v);check(v+' HTML 제약',Object.keys(await store(p)).length===n,{count:Object.keys(await store(p)).length});await close(p);await newTrip(p,'처리 단계 '+v,D,v,true);check(v+' 처리 단계 검증',Object.keys(await store(p)).length===n,Object.values(await store(p)).filter(t=>t.name==='처리 단계 '+v).map(t=>({days:t.dates.length})));await close(p);}});
test(14,'연말·월말·윤년 출발일로 3일 생성 후 날짜 배열 비교',async(p,c,check)=>{for(const [d,expected]of [['2026-12-31',['2026-12-31','2027-01-01','2027-01-02']],['2026-04-30',['2026-04-30','2026-05-01','2026-05-02']],['2028-02-28',['2028-02-28','2028-02-29','2028-03-01']]]){await newTrip(p,d,d);const s=Object.values(await store(p)).find(s=>s.name===d);check(d,JSON.stringify(s.dates)===JSON.stringify(expected),s.dates);}});
test(15,'CDP 시간대를 서울→LA→키리티마티로 변경 후 여행 열기',async(p,c,check)=>{const session=await c.newCDPSession(p);for(const timezoneId of ['Asia/Seoul','America/Los_Angeles','Pacific/Kiritimati']){await session.send('Emulation.setTimezoneOverride',{timezoneId:''});await session.send('Emulation.setTimezoneOverride',{timezoneId});await openTrip(p);check(timezoneId,JSON.stringify((await snap(p)).dates)===JSON.stringify([D,E,'2026-11-03']),(await snap(p)).dates);}});
test(16,'첫 장소를 기간 밖 2027-01-01에 배치 후 화면/저장 날짜 확인',async(p,c,check)=>{await move(p,0,'2027-01-01');check('기간 밖 날짜 노출',(await snap(p)).dates.includes('2027-01-01')&&(await p.locator('#resultList .item-name').allTextContents()).includes('첫 장소'),{dates:(await snap(p)).dates,visible:await p.locator('#resultList .item-name').allTextContents()});});
test(17,'11/1·11월 1일·2026-11-01 일정 입력 → 그룹/모호성 안내',async(p,c,check)=>{await add(p,'짧은 날짜','11/1');await add(p,'한국어 날짜','11월 1일');const s=await snap(p);const dates=[...new Set(s.records.map(r=>r.cells[1].v))];check('동일 날짜 정규화 또는 경고',!dates.includes('11/1')||/모호|연도.*확인/.test(await p.textContent('body')),{dates,toast:await p.textContent('#toast')});});
test(18,'종료<시작(13:00–12:00), 자정 넘김(23:00–01:00) 입력 → 구분 안내',async(p,c,check)=>{for(const t of ['13:00–12:00','23:00–01:00']){await add(p,'역전 시간 '+t,D,t);check(t+' 구분 안내',/자정|종료.*시작|시간.*오류/.test(await p.textContent('#planCheck')),{plan:await p.textContent('#planCheck'),saved:(await snap(p)).records.at(-1)?.cells[2]});}});
test(19,'24:00·25:30·오전 12시·시간 미정 입력, 실제 시간 파서 결과와 UI 경고 확인',async(p,c,check)=>{for(const t of ['24:00','25:30','오전 12시','시간 미정']){await add(p,t,D,t);const parsed=await p.evaluate(async t=>(await import('/js/routes.js')).parseTimeRange(t),t);const warning=/지원.*시간|시간.*형식|시간.*미정/.test(await p.textContent('#planCheck'));check(t,t==='오전 12시'?(parsed.start===0||warning):parsed.start===null,{parsed,warning,stored:true});}});
test(20,'날짜의 마지막 장소 다른 날 이동 → 원래 빈 날짜에 다시 추가',async(p,c,check)=>{await move(p,2,D);await add(p,'빈 날짜 재추가',E);check('빈 날짜 재배치',(await snap(p)).records.some(r=>r.cells[0].v==='빈 날짜 재추가'&&r.cells[1].v===E),names(await snap(p)));});
test(25,'동일 Place ID의 한·영·일 이름 검색 후 보관',async(p,c,check)=>{for(const name of ['서울역','Seoul Station','ソウル駅']){await search(p,name,{results:[place('same',name)]});await p.click('[data-travel-save="0"]');}check('동일 ID 중복 방지',(await snap(p)).library.length===1,(await snap(p)).library);});
test(26,'동명 다른 Place ID/주소 두 지점 검색·보관',async(p,c,check)=>{for(const [id,address]of [['branch1','서울 강남'],['branch2','부산 해운대']]){await search(p,id,{results:[place(id,'같은 상호',{address})]});await p.click('[data-travel-save="0"]');}check('다른 지점 독립 보관',(await snap(p)).library.length===2,(await snap(p)).library);});
test(27,'보관함 메모 저장 → 같은 ID의 빈 메모 결과 다시 보관',async(p,c,check)=>{await search(p,'보관',{results:[place()]});await p.click('[data-travel-save="0"]');await p.fill('[data-travel-note="0"]','소중한 메모');await p.locator('[data-travel-note="0"]').press('Tab');await search(p,'재보관',{results:[place()]});await p.click('[data-travel-save="0"]');check('기존 메모 보존',(await snap(p)).library[0].memo==='소중한 메모',(await snap(p)).library[0]);});
test(31,'보관함 메모 입력 직후 탭 전환/blur 없는 새로고침',async(p,c,check)=>{await search(p,'보관',{results:[place()]});await p.click('[data-travel-save="0"]');await p.fill('[data-travel-note="0"]','탭 전환 메모');await p.click('#travelPlanTab');check('탭 전환 시 메모 저장',(await snap(p)).library[0].memo==='탭 전환 메모',(await snap(p)).library[0]);await p.click('#travelLibraryTab');await p.fill('[data-travel-note="0"]','새로고침 직전');await p.reload();await openTrip(p);check('즉시 새로고침 메모 보존',(await snap(p)).library[0].memo==='새로고침 직전',(await snap(p)).library[0]);});
test(32,'같은 보관 장소 두 날짜에 배치 → 보관함에서만 삭제',async(p,c,check)=>{await search(p,'장소',{results:[place()]});await p.click('[data-travel-save="0"]');for(const day of [D,E]){await p.click('#travelLibraryTab');await p.click('[data-travel-add="0"]');await p.fill('#travelAssignDay',day);await p.click('#travelAssignForm button');}await p.click('#travelLibraryTab');await p.click('[data-travel-remove="0"]');const s=await snap(p);check('보관함 삭제는 일정 보존',s.library.length===0&&s.records.filter(r=>r.cells[0].v==='모의 장소').length===2,{library:s.library,records:names(s)});});
test(33,'첫 일정 수정 초안 입력 후 둘째 일정 수정 버튼 선택',async(p,c,check)=>{await edit(p);await p.fill('#scheduleMemo','저장 전 초안');await p.locator('#resultList [data-action="edit"]').nth(1).click({force:true});check('편집 대상 전환 시 초안 보호/안내',await p.inputValue('#scheduleMemo')==='저장 전 초안'||/미저장|저장.*먼저/.test(await p.textContent('#toast')),{memo:await p.inputValue('#scheduleMemo'),title:await p.textContent('#scheduleContext')});});
test(34,'교체 후보 선택 → 직접 다른 이름 입력 → 저장 후 이전 후보 좌표 혼합 여부',async(p,c,check)=>{await edit(p);await p.click('#schedulePlaceTab');await p.evaluate(()=>__mock.query['교체']={results:[{id:'replacement',name:'선택 후보',address:'후보 주소',lat:40,lng:140}]});await p.fill('#schedulePlaceQuery','교체');await p.click('#schedulePlaceSearch');await p.click('[data-schedule-pick="0"]');await p.fill('#scheduleName','직접 수정 이름');await p.click('#scheduleForm button[type=submit]');const s=await snap(p);const i=s.records.findIndex(r=>r.cells[0].v==='직접 수정 이름');check('후보 좌표와 직접 이름 혼합 방지',!s.places.some(e=>e.recordIndex===i&&e.place.id==='replacement'),{record:s.records[i],places:s.places});});
test(35,'시간·메모만 편집 → 검색 호출수/좌표 비교',async(p,c,check)=>{const before=await snap(p),n=await p.evaluate(()=>__mock.searches.length);await edit(p);await p.fill('#scheduleTime','11:00');await p.fill('#scheduleMemo','메모만');await p.click('#scheduleForm button[type=submit]');const s=await snap(p);check('재검색 없음',await p.evaluate(()=>__mock.searches.length)===n,await p.evaluate(()=>__mock.searches));check('좌표 유지',s.places[0].place.lat===before.places[0].place.lat,s.places[0]);});
test(36,'같은 시간의 두 일정 중 하나 다른 날짜로 이동 → 충돌 안내',async(p,c,check)=>{await move(p,0,E);const s=await snap(p);check('시간 유지',s.records.find(r=>r.cells[0].v==='첫 장소').cells[2].v==='10:00–11:00','10:00–11:00');check('겹치는 방문 시간 안내',/겹|충돌/.test(await p.textContent('#planCheck')),await p.textContent('#planCheck'));});
test(37,'같은 장소 하루 2회+다른 날 배치 → 한 방문 메모만 수정',async(p,c,check)=>{await search(p,'동일 장소',{results:[place()]});await p.click('[data-travel-save="0"]');for(const day of [D,D,E]){await p.click('#travelLibraryTab');await p.click('[data-travel-add="0"]');await p.fill('#travelAssignDay',day);await p.click('#travelAssignForm button');}await close(p);await p.click('#travelPlanTab');const rows=p.locator('#resultList > li.item').filter({hasText:'모의 장소'});await rows.first().locator('[data-action="edit"]').click();await p.fill('#scheduleMemo','이 방문만');await p.click('#scheduleForm button[type=submit]');const visits=(await snap(p)).records.filter(r=>r.cells[0].v==='모의 장소');check('방문별 독립 수정',visits.length===3&&visits.filter(r=>r.cells[4]?.v==='이 방문만').length===1,visits.map(r=>[r.cells[1].v,r.cells[4]?.v]));});
test(38,'이름 검색 필터 적용 → 이동 모달의 숨은 항목 기준 앞 위치 선택',async(p,c,check)=>{await p.fill('#workspaceSearch','둘째');await p.locator('#resultList [data-action="travel-move"]').click();const options=await p.locator('#travelAssignPosition option').allTextContents();await p.selectOption('#travelAssignPosition','0');await p.click('#travelAssignForm button');check('숨은 항목을 이름으로 식별해 배치',options.some(t=>t.includes('첫 장소'))&&names(await snap(p))[0]==='둘째 장소',{options,records:names(await snap(p))});});
test(39,'선택 일정 삭제 → 패널/이웃 대상 확인',async(p,c,check)=>{await p.locator('#resultList > li.item').first().click();await del(p);check('삭제 대상 패널 잔존 없음',!(await p.textContent('#placePanelBody')).includes('첫 장소'),await p.textContent('#placePanelBody'));check('삭제 대상 레코드 없음',!names(await snap(p)).includes('첫 장소'),names(await snap(p)));});
test(40,'드래그 시작 → Escape/목록 밖 드롭 → 원본 비교',async(p,c,check)=>{const before=names(await snap(p));await drop(p,'#resultList > li.item','#resultList',true);await p.keyboard.press('Escape');check('Escape 취소 원본 유지',JSON.stringify(names(await snap(p)))===JSON.stringify(before),names(await snap(p)));await drop(p,'#resultList > li.item','body');check('외부 드롭 원본 유지',JSON.stringify(names(await snap(p)))===JSON.stringify(before),names(await snap(p)));});
test(41,'행 자기 자신 위 합성 드래그/드롭 → records·updated·요청수 비교',async(p,c,check)=>{const before=await snap(p),n=await p.evaluate(()=>__mock.searches.length+__mock.routes.length);await drop(p,'#resultList > li.item','#resultList > li.item');const after=await snap(p);check('자기 드롭은 변경/저장/요청 없음',JSON.stringify(before)===JSON.stringify(after)&&n===await p.evaluate(()=>__mock.searches.length+__mock.routes.length),{beforeUpdated:before.updated,afterUpdated:after.updated});});
test(42,'드래그 시작 → 다른 날짜 필터 → 현재 대상 위 드롭 → 적용',async(p,c,check)=>{await p.evaluate(()=>{window.__dt=new DataTransfer();document.querySelector('#resultList > li.item').dispatchEvent(new DragEvent('dragstart',{bubbles:true,dataTransfer:__dt}));});await p.locator(`#mapDays [data-workspace-day="${E}"]`).click();await p.evaluate(()=>{document.querySelector('#resultList > li.item').dispatchEvent(new DragEvent('drop',{bubbles:true,dataTransfer:__dt}));});await p.click('#travelAssignForm button');const s=await snap(p);check('처음 잡은 항목만 이동',s.records.length===3&&s.records.find(r=>r.cells[0].v==='첫 장소').cells[1].v===E,s.records.map(r=>[r.cells[0].v,r.cells[1].v]));});
test(43,'삭제 → 새 장소 추가 → 이전 삭제 취소 기회와 후속 데이터 확인',async(p,c,check)=>{await del(p);await add(p,'후속 추가');const toast=await p.textContent('#toast');await p.click('#deleteUndo');const ns=names(await snap(p));check('이전 삭제 취소 접근 보존',ns.includes('첫 장소')&&ns.includes('후속 추가'),{toast,afterUndo:ns});});
