test(46,'삭제 확인 취소·Escape 닫기 → records/updated 비교',async(p,c,check)=>{for(const mode of ['취소','닫기(Escape와 동일 dismiss)']){const before=await snap(p);await del(p,0,false);const after=await snap(p);check(mode,JSON.stringify(before)===JSON.stringify(after),names(after));}});

test(1,'기존 검색 결과 확보 → 지연 검색 중 오프라인 전환 → 복구 및 재검색',async(p,c,check)=>{await search(p,'이전 결과',{results:[place()]});await search(p,'오프라인',{delay:400,results:[place('new','새 결과')]});await c.setOffline(true);await p.evaluate(()=>__mock.offline=true);await wait(p,500);check('실패 후 로딩/버튼 복원',await p.locator('#travelSearchForm button').isEnabled(),await p.textContent('#travelSearchStatus'));check('기존 결과/입력 유지',(await p.textContent('#travelSearchResults')).includes('모의 장소')&&await p.inputValue('#travelSearch')==='오프라인',await p.textContent('#travelSearchResults'));await c.setOffline(false);await p.evaluate(()=>__mock.offline=false);await search(p,'복구',{results:[place('recovered','복구 결과')]});check('복구 후 검색',/복구 결과/.test(await p.textContent('#travelSearchResults')),await p.textContent('#travelSearchResults'));});
test(2,'여행 생성·일정 추가·적용·검색에 동기 연속 submit 및 Enter+click 실행',async(p,c,check)=>{
 const before=Object.keys(await store(p)).length;await p.click('#newTravel');await p.fill('#travelName','중복 제출');await p.fill('#travelStart',D);await p.evaluate(()=>{const f=document.querySelector('#newTravelForm');f.requestSubmit();f.requestSubmit();});check('여행 생성 중복 방지',Object.keys(await store(p)).length===before+1,Object.values(await store(p)).map(t=>t.name));
 await close(p);await p.click('#travelPlanTab');await p.click('#scheduleAdd');await p.fill('#scheduleName','중복 일정');await p.evaluate(()=>{const f=document.querySelector('#scheduleForm');f.requestSubmit();f.requestSubmit();});const newest=Object.values(await store(p)).filter(t=>t.name==='중복 제출').sort((a,b)=>b.updated-a.updated)[0];check('일정 추가 중복 방지',newest.records.length===1,names(newest));
 await search(p,'중복 검색',{delay:150,results:[place()]});await wait(p,200);await p.click('[data-travel-direct="0"]');const n=Object.values(await store(p)).reduce((n,t)=>n+t.records.length,0);await p.evaluate(()=>{const f=document.querySelector('#travelAssignForm');f.requestSubmit();f.requestSubmit();});const n2=Object.values(await store(p)).reduce((n,t)=>n+t.records.length,0);check('적용 중복 방지',n2-n===1,{before:n,after:n2});
 await p.click('#travelLibraryTab');await p.evaluate(()=>{__mock.query['Enter클릭']={delay:200,results:[]};document.querySelector('#travelSearch').value='Enter클릭';});await p.locator('#travelSearch').press('Enter');await p.locator('#travelSearchForm button').click({force:true});await wait(p,300);check('Enter+클릭 검색 요청 중복 방지',await p.evaluate(()=>__mock.searches.filter(s=>s.textQuery==='Enter클릭').length)===1,await p.evaluate(()=>__mock.searches));
});
test(4,'잘못된 키·리퍼러 제한·API 비활성화 모의 거부와 0결과를 비교; 로컬 편집',async(p,c,check)=>{for(const error of ['API_KEY_INVALID','RefererNotAllowedMapError REQUEST_DENIED','Places API has not been used or is disabled']){await search(p,error,{error});check(error,/검색하지 못/.test(await p.textContent('#travelSearchStatus')),await p.textContent('#travelSearchStatus'));}await search(p,'0건',{results:[]});check('0결과와 거부 구분',!/검색하지 못/.test(await p.textContent('#travelSearchStatus')),await p.textContent('#travelSearchStatus'));await add(p,'권한 오류 뒤 로컬 편집');check('로컬 편집 가능',names(await snap(p)).includes('권한 오류 뒤 로컬 편집'),names(await snap(p)));});
test(5,'지도 인증 실패 콜백 후 로컬 편집; 키 제거로 reload → 초안 손실 확인',async(p,c,check)=>{await p.evaluate(()=>window.gm_authFailure());await add(p,'무효화 후 로컬 편집');check('키 무효화 후 편집 유지',names(await snap(p)).includes('무효화 후 로컬 편집'),await p.textContent('#keyStatus'));await edit(p);await p.fill('#scheduleMemo','키 제거 전 미저장');await p.locator('[data-open="settingsDialog"]:visible').first().click();await p.fill('#apiKeyInput','');await p.click('#keyForm button');await wait(p,300);await openTrip(p);await edit(p);check('키 제거 시 입력 보호',await p.inputValue('#scheduleMemo')==='키 제거 전 미저장',{memo:await p.inputValue('#scheduleMemo')});});
test(6,'A 지연·B 빠른 검색 응답 역전; 검색 중 여행 전환',async(p,c,check)=>{await search(p,'느린 A',{delay:700,results:[place('A','A 결과')]});await p.evaluate(()=>{__mock.query['빠른 B']={results:[{id:'B',name:'B 결과',address:'B',lat:35,lng:139}]};document.querySelector('#travelSearch').value='빠른 B';document.querySelector('#travelSearchForm').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));});await wait(p,850);check('B 최신 응답 유지',/B 결과/.test(await p.textContent('#travelSearchResults'))&&!/A 결과/.test(await p.textContent('#travelSearchResults')),await p.textContent('#travelSearchResults'));await search(p,'전환 중',{delay:500,results:[place('old','이전 여행 결과')]});await openTrip(p,'negative-B');await wait(p,650);check('다른 여행 결과 오염 없음',!/이전 여행 결과/.test(await p.textContent('#travelSearchResults')),await p.textContent('#travelSearchResults'));});
test(21,'도시 없는 동명 상호의 서로 다른 국가·도시 응답 표시',async(p,c,check)=>{await search(p,'스타벅스',{results:[place('jp','스타벅스',{address:'일본 도쿄 시부야'}),place('kr','스타벅스',{address:'대한민국 서울 강남'})]});const text=await p.textContent('#travelSearchResults');check('주소로 동명 구분',text.includes('도쿄')&&text.includes('서울'),text);});
test(22,'검색 시작 직전/요청 중 검색어 변경 → 결과 검색어 표기',async(p,c,check)=>{await search(p,'원래 검색어',{delay:300,results:[place('A','원래 결과')]});await p.fill('#travelSearch','바꾼 검색어');await wait(p,400);const text=await p.textContent('#travelSearchStatus');check('결과가 요청 검색어와 연결됨',text.includes('원래 검색어'),{input:await p.inputValue('#travelSearch'),status:text,results:await p.textContent('#travelSearchResults')});});
test(23,'이전 검색 버튼의 DOM 참조 보관 → 0결과 검색 → 이전 버튼 클릭',async(p,c,check)=>{await search(p,'먼저',{results:[place()]});await p.evaluate(()=>window.__oldButton=document.querySelector('[data-travel-save]'));await search(p,'빈 결과',{results:[]});await p.evaluate(()=>window.__oldButton.click());check('이전 장소 추가 없음',(await snap(p)).library.length===0&&await p.locator('#travelSearchResults button').count()===0,{library:(await snap(p)).library,buttons:await p.locator('#travelSearchResults button').count()});});
test(24,'모바일 390px에서 긴 한글 이름/주소 30개 모의 결과 표시 → 버튼 경계·가로 스크롤 확인',async(p,c,check)=>{await p.setViewportSize({width:390,height:844});await search(p,'긴 결과',{results:Array.from({length:30},(_,i)=>place('long'+i,'긴한국어상호'.repeat(30),{address:'대한민국 서울특별시 '.repeat(40)}))});const metrics=await p.evaluate(()=>{const a=[...document.querySelectorAll('#travelSearchResults button')];return{count:a.length,overflow:document.documentElement.scrollWidth>innerWidth,offscreen:a.filter(b=>{const r=b.getBoundingClientRect();return r.left<0||r.right>innerWidth}).length};});check('다수 긴 결과 버튼 잘림 없음',metrics.count===60&&!metrics.overflow&&metrics.offscreen===0,metrics);});
