const initial60=cases.get(60).fn;
cases.get(60).fn=async(p,c,check)=>{
 await initial60(p,c,check);
 for(const kind of ['updated','records','cells','library','dates','mapping']) {
  await p.reload();const base=trip();
  if(kind==='updated')base.updated='invalid timestamp';
  if(kind==='records')base.records={invalid:true};
  if(kind==='cells')base.records[0].cells={invalid:true};
  if(kind==='library')base.library={invalid:true};
  if(kind==='dates')base.dates={invalid:true};
  if(kind==='mapping')base.mapping=null;
  await p.evaluate(([k,a,b])=>localStorage.setItem(k,JSON.stringify({[a.id]:a,[b.id]:b})),[KEY,base,trip('negative-B','부정 테스트 B',[['다른 여행 장소',D]])]);
  const errors=[];const onError=e=>errors.push(e.message);p.on('pageerror',onError);
  await p.click('#savedTravels');await p.locator('#travelHistoryDialog').waitFor({state:'visible'});
  const buttons=p.locator('[data-travel-open="negative-A"]');
  if(await buttons.count())await buttons.first().click();
  await wait(p,100);const text=await p.textContent('body');
  check(kind+' 타입 변조 안전 처리',errors.length===0&&!/Invalid Date/.test(text),{errors,invalidDate:/Invalid Date/.test(text),rows:await p.locator('#resultList .item-name').allTextContents()});
  p.off('pageerror',onError);await close(p);
 }
};
