async function main() {
 fs.mkdirSync(OUT,{recursive:true});
 browser=await chromium.launch({executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',headless:true,args:['--no-sandbox']});
 const only=process.env.ONLY?new Set(process.env.ONLY.split(',').map(Number)):null;
 const order=[7,8,57,58,60,3,9,10, ...Array.from({length:78},(_,i)=>i+1).filter(i=>![7,8,57,58,60,3,9,10].includes(i))];
 for(const id of order) {
  if(only&&!only.has(id))continue;
  const t=cases.get(id),record={id,started:new Date().toISOString(),steps:t?.steps||'',checks:[],errors:[],consoleErrors:[],mode:'브라우저 UI + 모의 Google SDK/지도 호출 기록',screenshots:[]};
  const c=await browser.newContext({viewport:{width:1440,height:900},locale:'ko-KR',...(id===15?{}:{timezoneId:'Asia/Seoul'}),acceptDownloads:true});
  await c.route('**/*',route=>{const url=route.request().url();if(!url.startsWith(BASE)&&!url.startsWith('blob:')&&!url.startsWith('data:'))return route.abort('blockedbyclient');if(new URL(url).pathname==='/js/mapview.js')return route.fulfill({contentType:'text/javascript',body:fs.readFileSync(path.join(__dirname,'mapview-mock.js'),'utf8')});return route.continue();});
  await c.addInitScript({path:path.join(__dirname,'google-mock.js')});
  const a=trip(),b=trip('negative-B','부정 테스트 B',[['다른 여행 장소',D,'09:00']]);
  await c.addInitScript(({a,b,id,KEY})=>{if(!localStorage.getItem('negative-seeded')){localStorage.setItem(KEY,JSON.stringify({[a.id]:a,[b.id]:b}));localStorage.setItem('googleMapsApiKey','NOT_A_REAL_KEY_NEGATIVE_TEST');localStorage.setItem('negative-seeded','1');}if(id===28)__mock.details.p1={error:'NETWORK_FAIL'};if(id===29)__mock.details.p0={photos:['/negative-photo-1','/negative-photo-2','/negative-photo-3']};if(id===47||id===48)__mock.mapDelay=600;},{a,b,id,KEY});
  const p=await c.newPage();p.setDefaultTimeout(4000);p.on('pageerror',e=>record.errors.push(e.message));p.on('console',m=>{if(m.type()==='error')record.consoleErrors.push(m.text().replace(/key=[^&\s]+/g,'key=REDACTED'));});
  const check=(name,ok,actual)=>record.checks.push({name,status:ok===null?'검증 불가':ok==='해당 없음'?'해당 없음':ok?'통과':'결함 확인',actual});
  try {await p.goto(BASE);await openTrip(p);if(t)await t.fn(p,c,check);else check('미실행',null,'재현 절차 미구현');}
  catch(e){record.harnessError=e.message;check('추가 실행 중단',null,e.message);}
  try{const png=`${String(id).padStart(2,'0')}.png`;await p.screenshot({path:path.join(OUT,png),fullPage:true});record.screenshots.push(png);record.finalDOM={toast:await p.textContent('#toast'),save:await p.textContent('#travelSaveStatus'),rows:await p.locator('#resultList .item-name').allTextContents()};record.mock=await p.evaluate(()=>({searches:__mock.searches,fields:__mock.fields,routes:__mock.routes,markers:__mock.markers,legs:__mock.legs}));}catch(e){record.captureError=e.message;}
  record.status=record.checks.some(c=>c.status==='결함 확인')?'결함 확인':record.checks.some(c=>c.status==='검증 불가')?'검증 불가':'통과';
  record.finished=new Date().toISOString();fs.writeFileSync(path.join(OUT,`${String(id).padStart(2,'0')}.json`),JSON.stringify(record,null,2));results.push(record);console.log(id,record.status,record.harnessError||'');await c.close();
 }
 await browser.close();
 const all=fs.readdirSync(OUT).filter(n=>/^\d\d\.json$/.test(n)).map(n=>JSON.parse(fs.readFileSync(path.join(OUT,n))));fs.writeFileSync(path.join(OUT,'results.json'),JSON.stringify(all.sort((a,b)=>a.id-b.id),null,2));
 console.log('TOTAL',Object.fromEntries(['통과','결함 확인','검증 불가'].map(s=>[s,all.filter(a=>a.status===s).length])));process.exitCode=all.some(a=>a.harnessError)?2:all.some(a=>a.status==='결함 확인')?1:0;
}
main().catch(async e=>{console.error(e);if(browser)await browser.close();process.exitCode=1;});
